  // 讓作用中的書籤保持可見（橫向書籤列）
  function setActiveDay(btn) {
    var bar = document.getElementById('dayBar');
    if (!bar || !btn) return;
    var btns = bar.querySelectorAll('.daybar-btn');
    for (var i = 0; i < btns.length; i++) {
      var on = btns[i] === btn;
      btns[i].classList.toggle('active', on);
      btns[i].setAttribute('aria-selected', on ? 'true' : 'false');
    }
    if (bar.scrollWidth > bar.clientWidth) {
      var left = btn.offsetLeft - (bar.clientWidth - btn.offsetWidth) / 2;
      if (left < 0) left = 0;
      try { bar.scrollTo({ left: left, behavior: 'smooth' }); }
      catch (err) { bar.scrollLeft = left; }
    }
  }

  // 書籤列下方的黏性高度（頂部導覽 + 書籤列）
  function stickyOffset() {
    var nav = document.querySelector('.nav');
    var wrap = document.getElementById('dayBarWrap');
    var nh = nav ? nav.offsetHeight : 58;
    var dh = (wrap && !wrap.hidden) ? wrap.offsetHeight : 0;
    return nh + dh + 14;
  }

  // ── 交互：日子書籤（點擊跳轉 + scrollspy 高亮）──
  function initDayBar() {
    var bar = document.getElementById('dayBar');
    if (!bar) return;
    var btns = Array.prototype.slice.call(bar.querySelectorAll('.daybar-btn'));
    var days = Array.prototype.slice.call(document.querySelectorAll('.day'));
    if (!btns.length || !days.length) return;

    var byDay = {};
    btns.forEach(function (b) { byDay[b.getAttribute('data-day')] = b; });

    bar.addEventListener('click', function (e) {
      var btn = e.target && e.target.closest ? e.target.closest('.daybar-btn') : null;
      if (!btn) return;
      var el = document.getElementById('day-' + btn.getAttribute('data-day'));
      if (!el) return;
      el.classList.add('in'); // 先解除入場位移，量測才不會偏移
      var top = el.getBoundingClientRect().top + window.pageYOffset - stickyOffset();
      window.scrollTo({ top: top < 0 ? 0 : top, behavior: 'smooth' });
      setActiveDay(btn);
    });

    // scrollspy：滾動時把最靠近黏性頂部的那一天標為作用中
    var ticking = false;
    function compute() {
      ticking = false;
      var off = stickyOffset() + 10;
      var current = days[0];
      for (var i = 0; i < days.length; i++) {
        if (days[i].getBoundingClientRect().top - off <= 0) current = days[i];
      }
      var n = current.getAttribute('data-day');
      if (byDay[n] && !byDay[n].classList.contains('active')) setActiveDay(byDay[n]);
    }
    function onScroll() {
      if (ticking) return;
      ticking = true;
      if (window.requestAnimationFrame) window.requestAnimationFrame(compute);
      else setTimeout(compute, 100);
    }
    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', onScroll, { passive: true });
    compute();
  }

