      return;
    }

    // 依 分類 分組（維持本地目錄的分類順序，未知分類排到最後）
    var groups = {}, order = [];
    records.forEach(function (rec) {
      var idKey = String(rf(rec, '項目ID') || '').trim();
      var title = String(rf(rec, '準備項目') || '').trim();
      var cat = String(rf(rec, '分類') || '').trim() || '其他';
      var item = {
        recordId: rec.id,
        title: title,
        icon: iconFor(idKey, title),
        jessie: !!rf(rec, 'Jessie'),
        kiwis: !!rf(rec, 'Kiwis'),
        who: String(rf(rec, '由誰準備') || '').trim()
      };
      if (!groups[cat]) { groups[cat] = []; order.push(cat); }
      groups[cat].push(item);
    });
    order.sort(function (a, b) {
      var ia = CATEGORY_ORDER.indexOf(a); if (ia < 0) ia = CATEGORY_ORDER.length;
      var ib = CATEGORY_ORDER.indexOf(b); if (ib < 0) ib = CATEGORY_ORDER.length;
      return ia - ib;
    });

    var html = '<div class="pack-head">' +
      '<span>準備項目</span>' +
      '<span class="ph-person"><span class="mini-avatar a1" aria-hidden="true">J</span>Jessie 是否準備好</span>' +
      '<span class="ph-person"><span class="mini-avatar a2" aria-hidden="true">K</span>Kiwis 是否準備好</span>' +
      '<span>由誰準備</span></div>';

    order.forEach(function (cat) {
      html += '<div class="pack-group"><div class="pack-group-title">' +
        (CATEGORY_ICON[cat] || '📦') + ' ' + esc(cat) + '</div>';
      groups[cat].forEach(function (it, idx) {
        html += checklistRowHTML(it, idx);
      });
      html += '</div>';
    });
    host.innerHTML = html;

    bindChecklistEvents(host);

    var c1 = 0, c2 = 0;
    records.forEach(function (rec) {
      if (rf(rec, 'Jessie')) c1++;
      if (rf(rec, 'Kiwis')) c2++;
    });
    updateProgress(c1, c2, records.length);
  }

  function checklistRowHTML(it, idx) {
    return '<div class="pack-row' + (idx % 2 ? ' zebra' : '') + '">' +
      '<div class="pack-item"><span class="ic">' + it.icon + '</span><span>' + esc(it.title) + '</span></div>' +
      '<div class="pack-cell"><span class="cell-lbl">Jessie</span>' +
        '<label class="pcheck" data-person="m1" title="Jessie 是否準備好"><input type="checkbox" data-person="m1" data-record-id="' + esc(it.recordId) + '" data-field="Jessie"' + (it.jessie ? ' checked' : '') + ' aria-label="Jessie 是否準備好：' + esc(it.title) + '"><span class="pbox">✓</span></label>' +
      '</div>' +
      '<div class="pack-cell"><span class="cell-lbl">Kiwis</span>' +
        '<label class="pcheck" data-person="m2" title="Kiwis 是否準備好"><input type="checkbox" data-person="m2" data-record-id="' + esc(it.recordId) + '" data-field="Kiwis"' + (it.kiwis ? ' checked' : '') + ' aria-label="Kiwis 是否準備好：' + esc(it.title) + '"><span class="pbox">✓</span></label>' +
      '</div>' +
      '<div class="pack-cell"><span class="cell-lbl">由誰準備</span>' +
        '<select class="pwho" data-record-id="' + esc(it.recordId) + '" data-field="由誰準備" data-prev="' + esc(it.who) + '" aria-label="由誰準備：' + esc(it.title) + '">' +
          WHO_OPTS.map(function (o) {
            return '<option value="' + esc(o.v) + '"' + (it.who === o.v ? ' selected' : '') + '>' + esc(o.label) + '</option>';
          }).join('') +
        '</select>' +
      '</div>' +
    '</div>';
  }

  // 事件：勾選 → 樂觀 UI + 寫入智能表；由誰準備 → 寫入 SELECT（失敗回滾）
  function bindChecklistEvents(host) {
    Array.prototype.slice.call(host.querySelectorAll('.pcheck input')).forEach(function (box) {
      box.addEventListener('change', function () {
        var recordId = box.getAttribute('data-record-id');
        var field = box.getAttribute('data-field');
        var val = box.checked;
        updateProgressFromDom(); // 樂觀：先即時回饋進度條
        tableData.update(recordId, kv(field, val)).then(function (ok) {
          if (!ok) { box.checked = !val; updateProgressFromDom(); } // 失敗回滾
        });
      });
    });
    Array.prototype.slice.call(host.querySelectorAll('.pwho')).forEach(function (sel) {
      sel.addEventListener('change', function () {
        var recordId = sel.getAttribute('data-record-id');
        var field = sel.getAttribute('data-field');
        var prev = sel.getAttribute('data-prev') || '';
        sel.setAttribute('data-prev', sel.value);
        tableData.update(recordId, kv(field, sel.value)).then(function (ok) {
          if (!ok) { sel.value = prev; sel.setAttribute('data-prev', prev); }
        });
      });
    });
  }

  // 樂觀進度：依 DOM 目前勾選狀態即時計數（寫入落庫前先回饋）
  function updateProgressFromDom() {
    var boxes = document.querySelectorAll('#packTable .pcheck input');
    var total = boxes.length / 2, c1 = 0, c2 = 0;
    Array.prototype.forEach.call(boxes, function (b) {
      if (!b.checked) return;
      if (b.getAttribute('data-person') === 'm1') c1++; else c2++;
    });
    updateProgress(c1, c2, total);
  }

  function updateProgress(done1, done2, total) {
    setPersonBar('pBar1', 'pCount1', done1, total);
    setPersonBar('pBar2', 'pCount2', done2, total);
  }
  function setPersonBar(barId, cntId, done, total) {
    var bar = document.getElementById(barId);
    var cnt = document.getElementById(cntId);
    if (bar) bar.style.width = (total ? (done / total * 100) : 0) + '%';
    if (cnt) cnt.textContent = '已備 ' + done + ' / 共 ' + total;
  }

  function checklistLoadingHTML() {
    var rows = '';
    for (var i = 0; i < 6; i++) {
      rows += '<div class="pk-skel-row">' +
        '<span class="pk-skel"></span><span class="pk-skel pk-skel-box"></span>' +
        '<span class="pk-skel pk-skel-box"></span><span class="pk-skel pk-skel-sel"></span>' +
      '</div>';
    }
    return '<div class="pk-state" role="status" aria-live="polite">' +
      '<div class="pk-state-head">⏳ 正在讀取清單…</div>' + rows + '</div>';
  }

  function checklistEmptyHTML() {
    return '<div class="pk-state" role="status">' +
      '<div class="pk-state-ico">🗂️</div>' +
      '<div class="pk-state-title">清單暫時無法顯示</div>' +
      '<div class="pk-state-desc">未能從智能表讀取到準備項目，請確認網路連線後重試。</div>' +
      '<button type="button" class="pk-retry" data-retry>重新載入</button>' +
    '</div>';
  }

  // ── 量測頂部導覽高度，供黏性書籤列定位 ──
  function syncNavHeight() {
    var nav = document.querySelector('.nav');
    if (!nav) return;
    document.documentElement.style.setProperty('--nav-h', nav.offsetHeight + 'px');
  }

  // ── 初始化 ──
  renderDays();
  renderSpots();
  renderTips();
  // 清單渲染掛在 tableData.onChange（reload 成功 / 宿主 onChange 都會觸發）
  tableData.onChange(renderChecklist);
  renderChecklist();
  initNav();
  initReveal();
  initScrollSpy();
  initToTop();
  syncNavHeight();
  renderDayBar();
  window.addEventListener('resize', syncNavHeight, { passive: true });

  // 回到前景 / 視窗聚焦時重拉，讓另一人（Jessie ↔ Kiwis）的改動即時出現
  document.addEventListener('visibilitychange', function () {
    if (!document.hidden) tableData.reload();
  });
  window.addEventListener('focus', function () { tableData.reload(); });
})();
